 if(state.editing){content.append(actions(button('撤回未保存改稿',()=>{state.editing=false;render();toast('已撤回未保存改动，恢复上一保存版本。');}),button('保存改稿',()=>{if(state.platform==='wechat'){if(!titleEdit.value.trim()||!bodyEdit.value.trim()){toast('标题和正文不能为空。');return;}}else if(cardEdits.some(c=>!c.title.value.trim()||!c.body.value.trim())||!xhsTitleEdit.value.trim()||!xhsBodyEdit.value.trim()||xhsTitleEdit.value.length>20||xhsBodyEdit.value.length>1000){toast('图卡及小红书文案不能为空；小红书标题最多20字、正文1000字。');return;}record();if(state.platform==='wechat'){t.title=titleEdit.value.trim();t.body=bodyEdit.value.trim();}else{t.cards=t.cards.map((c,i)=>({...c,title:cardEdits[i].title.value.trim(),body:cardEdits[i].body.value.trim()}));t.xhsTitle=xhsTitleEdit.value.trim();t.xhsText=xhsBodyEdit.value.trim();}t.version++;t.status='待审核';t.verified=false;t.publishedUrl='';state.editing=false;record();render();toast('改稿已保存为新版本，原审核已撤销。');},'button primary')));}main.append(content);
