function recordPublication(){const t=state.task;if(state.editing){toast('请先保存或撤回改稿。');return;}if(t.status!=='审核通过'&&t.status!=='已记录手动发布（模拟）'){toast('请先完成演示核验并通过审核。');return;}modal('记录手动发布 · 仅模拟',(d,close)=>{const url=input('https://example.invalid/prototype-demo');append(d,node('p','muted','不会访问此地址，也不会发布内容。实际流程应先复制，再到平台后台预览并由人工发布。'),field('模拟发布 URL',url,'仅接受 http(s)；建议保留 example.invalid 演示地址。'),button('保存模拟记录',()=>{try{const u=new URL(url.value);if(!['http:','https:'].includes(u.protocol)||u.username||u.password)throw Error();}catch(_){toast('请输入有效 http(s) 模拟地址，不能包含账户密码。');return;}t.publishedUrl=url.value;t.status='已记录手动发布（模拟）';record();close();render();toast('仅记录了本会话模拟 URL；没有真实外发。');},'button primary'));});}
